//! Cargo-driven `netcfgx.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is netcfgx-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x701f0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7febd000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7febd000000u64)),
        o => panic!("netcfgx-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:uuid", "engine:wine", "import:rpcrt4", "import:setupapi", "import:advapi32", "import:iphlpapi", "import:dhcpcsvc", "import:ole32", "import:user32", "import:comctl32", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["body", "engine:uuid", "engine:wine", "import:rpcrt4", "import:setupapi", "import:advapi32", "import:iphlpapi", "import:dhcpcsvc", "import:ole32", "import:user32", "import:comctl32", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "engine:uuid", "engine:wine", "import:rpcrt4", "import:setupapi", "import:advapi32", "import:iphlpapi", "import:dhcpcsvc", "import:ole32", "import:user32", "import:comctl32", "import:ws2_32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/netcfgx",
        "dll/win32/netcfgx",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x600",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("netcfgx-rust")
        .rc("dll/win32/netcfgx/netcfgx.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/netcfgx/netcfgx.spec", "netcfgx.dll")
        .spec_stubs()
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("base/services/dhcpcsvc/dhcpcsvc.spec", "dhcpcsvc.dll", "dhcpcsvc")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
